// Query HA history API for state changes over the last 24 hours.
// Returns events sorted by last_changed descending, limited to 5000 entries.
var base = (env.get('HA_URL') || 'http://homeassistant.local:8123').replace(/\\/+$/, '');
var token = env.get('HA_TOKEN');
if (!base || !token) {
  node.status({fill:'red',shape:'ring',text:'missing HA_URL/HA_TOKEN'});
  var miss = [];
  if (!base) { miss.push('HA_URL'); }
  if (!token) { miss.push('HA_TOKEN'); }
  msg._error = 'missing ' + miss.join(', ') + ' in /root/.node-red/.env';
  msg.topic = 'ha/error';
  return [null, null, msg];
}
msg.method = 'GET';
msg.ret = 'obj';
// Format: last_changed=2026-10-19T00:00:00.000000+00:00&entities=light.*&limit=5000&sort_order=desc
var since = new Date(Date.now() - 24 * 60 * 60 * 1000);
var sinceStr = since.toISOString().slice(0, 19).replace('T', ' ');
msg.url = base + '/api/history/events?last_changed=' + encodeURIComponent(sinceStr) + '&entities=light.*,switch.*,media_player.*,cover.*,lock.*&limit=5000&sort_order=desc';
msg.headers = {Authorization: 'Bearer ' + token};
msg.rejectUnauthorized = false;
node.status({fill:'blue',shape:'dot',text:'polling history'});
return [msg, null];

// Shape history events into chart data: [{t: timestamp, payload: count}]
if (msg.error || !msg.statusCode || msg.statusCode >= 400) {
  node.status({fill:'red',shape:'ring',text:'unreachable'});
  msg._error = msg.error ? String(msg.error.message || msg.error)
    : ('HTTP ' + (msg.statusCode || '?'));
  msg.topic = 'ha/error';
  return [null, null, msg];
}
var events = Array.isArray(msg.payload) ? msg.payload : [];
var byHour = {};
var now = Date.now();
var hourBucket = 3600000;

// Count changes per hour, last 24h
for (var i = 0; i < events.length; i++) {
  var e = events[i];
  if (!e || !e.event_id || !e.last_changed) { continue; }
  var ts = new Date(e.last_changed);
  if (isNaN(ts.getTime())) { continue; }
  // Only count controllable domains
  var domain = e.entity_id.split('.')[0];
  if (!['light','switch','media_player','cover','lock'].indexOf(domain) >= 0) { continue; }
  if (e.event_type !== 'state_changed') { continue; }
  var bucket = Math.floor((now - ts.getTime()) / hourBucket);
  if (bucket < 0 || bucket >= 24) { continue; }
  byHour[bucket] = (byHour[bucket] || 0) + 1;
}

// Build time-series data with 1-hour resolution
var result = [];
for (var h = 23; h >= 0; h--) {
  var ts = new Date(now - h * hourBucket);
  var count = byHour[23 - h] || 0;
  result.push({
    t: ts,
    payload: count
  });
}

node.status({fill:'green',shape:'dot',text:'chart ready'});
return [result, null];
